package pe.vichaval.gestionriego.caja.dto;
import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDate;
public class EgresoForm{@NotNull private LocalDate fecha=LocalDate.now();@NotBlank private String concepto;private String descripcion;@NotNull@DecimalMin("0.01")private BigDecimal monto;@NotBlank private String metodo="EFECTIVO";@NotBlank private String comprobante;public LocalDate getFecha(){return fecha;}public void setFecha(LocalDate v){fecha=v;}public String getConcepto(){return concepto;}public void setConcepto(String v){concepto=v;}public String getDescripcion(){return descripcion;}public void setDescripcion(String v){descripcion=v;}public BigDecimal getMonto(){return monto;}public void setMonto(BigDecimal v){monto=v;}public String getMetodo(){return metodo;}public void setMetodo(String v){metodo=v;}public String getComprobante(){return comprobante;}public void setComprobante(String v){comprobante=v;}}
